				const same = (k) => !!k && k.kind === "t" && k.key === t;
				if (same(y.edit)) return "<li class=\"ty-row editing\"><span class=\"ty-sp\"></span><label class=\"sr-only\" for=\"dpmTyEd\">类型名称</label><input class=\"fld" + (y.err ? " bad" : "") + "\" id=\"dpmTyEd\" value=\"" + esc(t) + "\" maxlength=\"20\" autocomplete=\"off\"" + (y.err ? " aria-invalid=\"true\" aria-describedby=\"dpmTyEdE\"" : "") + "><button type=\"button\" class=\"btn sm\" data-ty-cancel>取消</button><button type=\"button\" class=\"btn sm primary\" data-ty-save>保存</button></li>" + (y.err ? "<li class=\"wl-err\" id=\"dpmTyEdE\">" + esc(y.err) + "</li>" : "");
