			/** 前端先查一遍（空 / 超长 / 重名 / 保留名），服务端同样校验。 */
			typeErr(v, kind, skip) {
				const w = kind === "t" ? "类型" : "类型组";
				if (!v) return w + "名不能为空";
				if (v.length > 20) return w + "名不能超过 20 字";
				if (v === skip) return "";
				if (kind === "t") {
					if (v === "无类型") return "「无类型」是保留名";
					if (this.tyTask) return this.taskTypes().includes(v) ? "已经有类型「" + v + "」了" : "";
					if (this.linkTypes.includes(v)) return "已经有类型「" + v + "」了（在「" + this.tyGroupName(this.tyGroupOf(v)) + "」里）";
				} else if (v === "未归类" || this.typeGroups.some((g) => g.name === v)) return "已经有类型组「" + v + "」了";
				return "";
			}
			/** 类型弹窗里的写操作：成功后刷新看板；失败时编辑 / 新增中的放进行内错误，否则 toast 点名。 */
			/** 0.25 类型写操作串行（先显示后保存时，后一笔可能依赖前一笔，如新加的类型马上被拖动）。 */
			tyChain = Promise.resolve();
			tyPend = 0;
			async tyPost(action, body) {
				try {
					const run = this.tyChain.then(() => post(action, body));
					this.tyChain = run.catch(() => void 0);
					this.tyPend++;
					const r = await run.finally(() => {
						this.tyPend--;
					});
					if (this.disposed) return null;
					if (!this.tyPend) {
						this.snap = r;
						this.render();
					}
					return { v: r.result };
				} catch (e) {
					const m = e instanceof ApiError ? e.message : String(e);
					const y = this.ty;
					if (y && (y.edit || y.adding)) {
						y.err = m;
						this.typesRender(y.edit ? "#dpmTyEd" : "#dpmTyNew");
					} else {
						this.host.toast(m, "err");
						await this.refresh();
						if (this.ty) this.typesRender();
					}
					return null;
				}
			}
			tyLand(sel, focus) {
				const n = this.root.querySelector(sel);
				if (n) {
					n.classList.add("landed");
					setTimeout(() => n.classList.remove("landed"), 450);
				}
				if (focus) this.root.querySelector(focus)?.focus({ preventScroll: true });
			}
			async typeAdd() {
				const y = this.ty;
				if (!y || !y.adding) return;
				const gid = y.adding;
				const v = (this.$("#dpmTyNew")?.value ?? "").replace(/\s+/g, " ").trim();
				y.err = this.typeErr(v, "t");
				if (y.err) {
					this.typesRender("#dpmTyNew");
					return;
				}
				if (this.tyTask && this.snap) {
					this.$("#dpmTyNew").value = "";
					this.snap.board.taskTypes = [...this.taskTypes(), v];
					this.typesRender("#dpmTyNew");
					this.tyLand("#dpmTyList [data-ty=\"" + CSS.escape(v) + "\"]");
				}
				const r = await this.tyPost(this.tyTask ? "tasktype/add" : "linktype/add", this.tyTask || gid === LOOSE ? { name: v } : {
					name: v,
					group: gid
				});
				if (!r) return;
				y.err = "";
				if (!this.tyTask) {
					this.typesRender("#dpmTyNew");
					this.tyLand("#dpmTyList [data-ty=\"" + CSS.escape(r.v) + "\"]");
				}
				this.host.toast(this.tyTask ? "已新增任务类型「" + r.v + "」，所有卡片都能选" : "已在「" + this.tyGroupName(gid) + "」新增类型「" + r.v + "」，所有卡片都能选");
			}
			async tySave() {
				const y = this.ty;
				const k = y?.edit;
				if (!y || !k) return;
				const v = (this.$("#dpmTyEd")?.value ?? "").replace(/\s+/g, " ").trim();
				const from = k.kind === "t" ? k.key : this.tyGroupName(k.key);
				if (v === from) {
					y.edit = null;
					y.err = "";
					this.typesRender();
					return;
				}
				y.err = this.typeErr(v, k.kind, from);
				if (y.err) {
					this.typesRender("#dpmTyEd");
					return;
				}
				if (k.kind === "t") {
					const r = await this.tyPost(this.tyTask ? "tasktype/rename" : "linktype/rename", {
						from,
						to: v
					});
					if (!r) return;
					y.edit = null;
					y.err = "";
					if (this.taskEdit && this.taskEdit.ty === from) this.taskEdit.ty = r.v.name;
					this.typesRender("#dpmTyList [data-ty=\"" + CSS.escape(r.v.name) + "\"] [data-ty-edit]");
					const n = r.v.links ?? r.v.tasks ?? 0;
					this.host.toast("「" + from + "」已改名为「" + r.v.name + "」" + (n ? "，" + n + " " + this.tyUnit + "一起更新" : ""));
				} else {
					const r = await this.tyPost("typegroup/rename", {
						id: k.key,
						to: v
					});
					if (!r) return;
					y.edit = null;
					y.err = "";
					this.typesRender("[data-tgid=\"" + CSS.escape(k.key) + "\"] [data-tg-edit]");
					this.host.toast("类型组「" + from + "」已改名为「" + r.v.name + "」");
				}
			}
			async tyDelete(k) {
				const y = this.ty;
				if (!y) return;
				y.confirm = null;
				if (k.kind === "t") {
					const r = await this.tyPost(this.tyTask ? "tasktype/delete" : "linktype/delete", { name: k.key });
					if (!r) return;
					if (this.taskEdit && this.taskEdit.ty === k.key) this.taskEdit.ty = "";
					this.typesRender();
					const n = r.v.links ?? r.v.tasks ?? 0;
					this.host.toast("已删除类型「" + k.key + "」" + (n ? "，" + n + " " + this.tyUnit + "改成无类型" : ""));
				} else {
					const nm = this.tyGroupName(k.key);
					const r = await this.tyPost("typegroup/delete", { id: k.key });
					if (!r) return;
					this.typesRender();
					this.host.toast("已删除类型组「" + nm + "」" + (r.v.types ? "，" + r.v.types + " 个类型移到「未归类」" : ""));
				}
			}
