		let rlCc = null;
		let rlPanel = null;
		let rlHd = null;
		let rlDet = null;
		let rlFr = null;
		let rlRbc = null;
		let rlPo = null;
		let rlSw = null;
		let rlRaf = 0;
		let rlRo = null;
		let rlMo = null;
